shader.agsl:
uniform float2 uCenter;
uniform float2 uSize;
uniform float uRadius;
uniform float uHue;
half4 main(float2 p) {
  float d = abs(length(p - uCenter * uSize) - uRadius);
  float ring = 1.0 - smoothstep(4.0, 7.0, d);
  float glow = exp(-d * 0.08) * 0.6;
  float3 c = 0.5 + 0.5 * cos(6.28318 * (uHue + float3(0.0, 0.33, 0.67)));
  float3 bg = float3(0.063, 0.094, 0.157);
  return half4(half3(bg + c * max(ring, glow)), 1.0);
}
